      case 7:
        return DKGStatus_WaitRound2Pkg();
      case 8:
        return DKGStatus_WaitingForFunds();
      case 9:
        return DKGStatus_Finalize();
      case 10:
        return DKGStatus_SharedAddress(
          dco_decode_String(raw[1]),
        );
      default:
        throw Exception("unreachable");
    }
  }

