      case VotingVoteCommitStage_Signing(
          proposalId: final proposalId,
          bundleIndex: final bundleIndex
        ):
        sse_encode_i_32(3, serializer);
        sse_encode_u_32(proposalId, serializer);
        sse_encode_u_32(bundleIndex, serializer);
